  wire out;

  TopModule uut (
    .a(a),
    .b(b),
    .c(c),
    .d(d),
    .out(out)
  );

  reg [3:0] i;
  reg expected;

  initial begin
    for (i = 0; i < 16; i = i + 1) begin
      {c, d, a, b} = i;
      #1;
      // Independent behavioral check derived directly from K-map description
      case (i)
        4'b0000: expected = 1; // cd=00, ab=00
        4'b0001: expected = 1; // cd=00, ab=01
        4'b0010: expected = 1; // cd=00, ab=10
        4'b0011: expected = 0; // cd=00, ab=11
        4'b0100: expected = 1; // cd=01, ab=00
        4'b0101: expected = 0; // cd=01, ab=01
        4'b0110: expected = 1; // cd=01, ab=10
        4'b0111: expected = 0; // cd=01, ab=11
        4'b1000: expected = 1; // cd=10, ab=00
        4'b1001: expected = 1; // cd=10, ab=01
        4'b1010: expected = 0; // cd=10, ab=10
        4'b1011: expected = 0; // cd=10, ab=11
        4'b1100: expected = 0; // cd=11, ab=00
        4'b1101: expected = 1; // cd=11, ab=01
        4'b1110: expected = 1; // cd=11, ab=10
